import{_ as e,c as a,o as t,a2 as o}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"API\\\\LanguageController","description":"","frontmatter":{"sidebarPos":2,"sidebarTitle":"API\\\\LanguageController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/api-language-controller.md","filePath":"system-reference/backend/http/controllers/api-language-controller.md","lastUpdated":1778363927000}'),s={name:"system-reference/backend/http/controllers/api-language-controller.md"},n=o('<h1 id="api-languagecontroller" tabindex="-1">API\\LanguageController <a class="header-anchor" href="#api-languagecontroller" aria-label="Permalink to &quot;API\\LanguageController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/API/LanguageController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers\\API</code><br><strong>Extends</strong>: <code>Illuminate\\Routing\\Controller</code></p><p>Serves all translation strings as a JSON payload for frontend consumption. Results are cached to a file store for 10 minutes to avoid recomputing translations on every request.</p><h2 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __construct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Translation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $translation)</span></span></code></pre></div><p>Injects the <code>JoeDixon\\Translation\\Drivers\\Translation</code> driver used to load translation files.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="index-request-request-jsonresponse" tabindex="-1"><code>index(Request $request): JsonResponse</code> <a class="header-anchor" href="#index-request-request-jsonresponse" aria-label="Permalink to &quot;`index(Request $request): JsonResponse`&quot;">​</a></h3><p>Returns a JSON object containing all application translations, keyed by locale and translation group.</p><p><strong>Caching behaviour</strong>:</p><table><thead><tr><th>Detail</th><th>Value</th></tr></thead><tbody><tr><td>Cache store</td><td><code>file</code></td></tr><tr><td>Cache key</td><td><code>modularous-languages</code></td></tr><tr><td>TTL</td><td>600 seconds (10 minutes)</td></tr></tbody></table><p>Translations are resolved via <code>app(&#39;translator&#39;)-&gt;getTranslations()</code> which aggregates group and single-line translation files across all registered modules and the base application.</p><h3 id="store-show-id-update-id-destroy-id" tabindex="-1"><code>store()</code>, <code>show($id)</code>, <code>update($id)</code>, <code>destroy($id)</code> <a class="header-anchor" href="#store-show-id-update-id-destroy-id" aria-label="Permalink to &quot;`store()`, `show($id)`, `update($id)`, `destroy($id)`&quot;">​</a></h3><p>Stub methods — not implemented. The controller is read-only; translation management is handled through translation files or a dedicated translation UI.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>The frontend fetches translations on initial page load via this endpoint and stores them in the Vue i18n instance, enabling <code>$t(&#39;key&#39;)</code> calls throughout the admin panel and public views.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><code>ManageTranslations</code> trait on <code>BaseController</code> — provides server-side translation fallback chain for module-specific keys</li></ul>',18),r=[n];function i(l,d,c,h,p,u){return t(),a("div",null,r)}const m=e(s,[["render",i]]);export{b as __pageData,m as default};
